package dev.eugheist.ttmodern;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
final class ImbuedCombatWorldAudit {
 private static final java.util.Map<BlockPos,net.minecraft.world.level.block.state.BlockState> OLD=new java.util.LinkedHashMap<>();
 private static net.minecraft.world.entity.animal.Cow target;private static volatile int entityId;static volatile boolean checked;
 private static void check(boolean ok,String label){EnchanterClientAudit.check(ok,"imbued combat world: "+label);}
 static void tick(Minecraft mc,int tick){
  if(tick==450){var uuid=mc.player.getUUID();mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(uuid);var level=p.serverLevel();p.connection.teleport(17.5,205,15.5,180,20);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,net.minecraft.world.item.ItemStack.EMPTY);for(var effect:java.util.List.of(InfusedPotions.AIR,InfusedPotions.FIRE,InfusedPotions.EARTH))p.addEffect(new net.minecraft.world.effect.MobEffectInstance(effect,3600));OLD.clear();for(int y=205;y<=209;y++)for(int z=13;z<=17;z++){var pos=new BlockPos(18,y,z);OLD.put(pos,level.getBlockState(pos));level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());}target=net.minecraft.world.entity.EntityType.COW.create(level);target.setNoAi(false);target.setNoGravity(true);target.setPos(20.25,205,15.5);level.addFreshEntity(target);entityId=target.getId();});}
  if(tick==460){var uuid=mc.player.getUUID();mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(uuid);target.setPos(20.25,205,15.5);target.setDeltaMovement(0,0,0);p.attack(target);check(target.getHealth()<target.getMaxHealth(),"actual ServerPlayer.attack damages target");check(ImbuedPotionEffects.tracked(target,false)&&ImbuedPotionEffects.tracked(target,true),"actual attack event tracks air/fire");for(var pos:OLD.keySet())check(p.serverLevel().getBlockState(pos).is(ThaumicTinkererModern.FORCEFIELD.get()),"actual attack creates exact earth wall");});}
  if(tick==470){var entity=mc.level.getEntity(entityId);check(entity!=null,"native spawned target synchronized");check(entity.getY()>205,"actual air impulses move target upward on client (y="+entity.getY()+")");check(entity.isOnFire(),"actual fire ignition metadata synchronized");int[] wisps={0};mc.particleEngine.iterateParticles(p->{if(p instanceof ImbuedFireWisp)wisps[0]++;});check(wisps[0]>=30,"actual fire packets create thirty-wisp batches (alive="+wisps[0]+")");for(var pos:OLD.keySet())check(mc.level.getBlockState(pos).is(ThaumicTinkererModern.FORCEFIELD.get()),"native forcefield block sync");check(!mc.level.noCollision(mc.player,new net.minecraft.world.phys.AABB(new BlockPos(18,207,15)).deflate(.1)),"client collision engine sees invisible forcefield");}
  if(tick==540){for(var pos:OLD.keySet())check(!mc.level.getBlockState(pos).is(ThaumicTinkererModern.FORCEFIELD.get()),"native block tick expiry synchronized");var uuid=mc.player.getUUID();mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(uuid);for(var pos:OLD.keySet())check(!p.serverLevel().getBlockState(pos).is(ThaumicTinkererModern.FORCEFIELD.get()),"authoritative field expiration");target.discard();for(var effect:java.util.List.of(InfusedPotions.AIR,InfusedPotions.FIRE,InfusedPotions.EARTH))p.removeEffect(effect);for(var entry:OLD.entrySet())p.serverLevel().setBlockAndUpdate(entry.getKey(),entry.getValue());OLD.clear();checked=true;System.out.println("TT IMBUED COMBAT WORLD AUDIT: ALL PASS (real player attack,air movement,fire network wisps/ignition,earth block/collision sync,native expiry)");});}
 }
}
